// build-playback.js
// Concatenate the three runtime files into a single playback bundle so a
// page can ship one <script> tag instead of three. The sources are each
// self-contained IIFEs that define their own globals (Neonic, PshiftPng,
// PshiftLoader), so straight concatenation preserves behavior.
//
// Run: node build-playback.js
// Out: neonic-playback.js

const fs = require('fs');

const SOURCES = [
  'logo-engine-standalone.js',
  'pshift-png.js',
  'pshift-loader.js',
];
const OUT = 'neonic-playback.js';

const banner =
  '// neonic-playback.js — auto-generated bundle of:\n' +
  SOURCES.map(s => '//   - ' + s).join('\n') + '\n' +
  '// Do not edit this file. Edit the sources and re-run `node build-playback.js`.\n\n';

const parts = SOURCES.map(f => fs.readFileSync(f, 'utf8'));
fs.writeFileSync(OUT, banner + parts.join('\n'));

const outBytes = fs.statSync(OUT).size;
const srcBytes = SOURCES.reduce((n, f) => n + fs.statSync(f).size, 0);
console.log(`wrote ${OUT}  (${outBytes} bytes, sources total ${srcBytes})`);
